// Print-Ready 6x9 Novel Manuscript Generated by The Scribe's Ledger

use crate::project::{BookProject, ChapterKind};
use anyhow::{Context, Result};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Looks for a `typst` executable in standard locations or PATH.
pub fn find_typst_binary() -> Option<PathBuf> {
    // 1. Check PATH
    if let Ok(output) = Command::new("typst").arg("--version").output() {
        if output.status.success() {
            return Some(PathBuf::from("typst"));
        }
    }

    // 2. Common Windows install locations (Cargo bin, WinGet, local AppData)
    let user_profile = std::env::var("USERPROFILE").unwrap_or_default();
    let candidates = [
        format!("{user_profile}\\.cargo\\bin\\typst.exe"),
        format!("{user_profile}\\AppData\\Local\\Microsoft\\WinGet\\Links\\typst.exe"),
        format!("{user_profile}\\AppData\\Local\\Programs\\typst\\typst.exe"),
        "C:\\Program Files\\typst\\typst.exe".to_string(),
        "C:\\ProgramData\\chocolatey\\bin\\typst.exe".to_string(),
    ];

    for path_str in candidates {
        let p = PathBuf::from(path_str);
        if p.exists() {
            return Some(p);
        }
    }

    None
}

/// Compiles a book project to a PDF using Typst.
/// Writes the generated Typst manuscript to `manuscript.typ` next to `output_pdf`
/// and invokes the Typst CLI.
pub fn compile_to_pdf(project: &BookProject, output_pdf: &Path) -> Result<PathBuf> {
    let typst_binary = find_typst_binary()
        .context("Typst compiler is not installed or not found in PATH / standard directories")?;

    let typst_source = compile_manuscript_to_typst(project);

    // Save manuscript.typ alongside the requested output pdf
    let parent = output_pdf.parent().unwrap_or_else(|| Path::new("."));
    fs::create_dir_all(parent)?;
    let typ_path = parent.join("manuscript.typ");
    fs::write(&typ_path, &typst_source)
        .with_context(|| format!("Failed to write generated Typst template to {:?}", typ_path))?;

    let status = Command::new(&typst_binary)
        .arg("compile")
        .arg(&typ_path)
        .arg(output_pdf)
        .status()
        .with_context(|| format!("Failed to execute Typst compiler at {:?}", typst_binary))?;

    if !status.success() {
        anyhow::bail!(
            "Typst compilation failed with exit code: {:?}",
            status.code()
        );
    }

    Ok(output_pdf.to_path_buf())
}

/// Checks if a line is a boilerplate heading such as `# Chapter 1` or `## Scene 1`.
pub fn is_boilerplate_scene_heading(line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    (lower.starts_with("# chapter") && !lower.contains(':'))
        || lower.starts_with("## scene")
        || lower.starts_with("# scene")
}

/// Replaces `$Title` and `$Author` (case-insensitive) placeholders in a string
/// with the project's title and author.
pub fn replace_placeholders(text: &str, title: &str, author: &str) -> String {
    let mut result = text.to_string();
    for p in ["$Title", "$TITLE", "$title"] {
        result = result.replace(p, title);
    }
    for p in ["$Author", "$AUTHOR", "$author"] {
        result = result.replace(p, author);
    }
    result
}

/// Converts basic Markdown into Typst syntax.
/// - `# Heading` -> `= Heading`
/// - `## Heading` -> `== Heading`
/// - `### Heading` -> `=== Heading`
/// - `**bold**` -> `*bold*`
/// - `*italic*` -> `_italic_`
/// - `<u>underline</u>` -> `#underline[underline]`
pub fn markdown_to_typst(markdown: &str) -> String {
    let mut out = String::with_capacity(markdown.len() + 64);
    let mut in_blockquote = false;

    for raw_line in markdown.lines() {
        let trimmed = raw_line.trim();

        if trimmed.is_empty() {
            if in_blockquote {
                out.push_str("]\n\n");
                in_blockquote = false;
            } else {
                out.push_str("\n\n");
            }
            continue;
        }

        if let Some(rest) = trimmed.strip_prefix("# ") {
            if in_blockquote {
                out.push_str("]\n\n");
                in_blockquote = false;
            }
            out.push_str("= ");
            format_inline_markdown_into(&mut out, rest.trim());
            out.push_str("\n\n");
        } else if let Some(rest) = trimmed.strip_prefix("## ") {
            if in_blockquote {
                out.push_str("]\n\n");
                in_blockquote = false;
            }
            out.push_str("== ");
            format_inline_markdown_into(&mut out, rest.trim());
            out.push_str("\n\n");
        } else if let Some(rest) = trimmed.strip_prefix("### ") {
            if in_blockquote {
                out.push_str("]\n\n");
                in_blockquote = false;
            }
            out.push_str("=== ");
            format_inline_markdown_into(&mut out, rest.trim());
            out.push_str("\n\n");
        } else if let Some(rest) = trimmed.strip_prefix('>') {
            if !in_blockquote {
                out.push_str("#quote(block: true)[\n");
                in_blockquote = true;
            }
            format_inline_markdown_into(&mut out, rest.trim());
            out.push('\n');
        } else {
            format_inline_markdown_into(&mut out, trimmed);
            out.push('\n');
        }
    }

    if in_blockquote {
        out.push_str("]\n\n");
    }

    out
}

/// Writes inline markdown spans (`**bold**`, `*italic*`, `<u>underline</u>`) converted to Typst markup directly into `out`.
fn format_inline_markdown_into(out: &mut String, input: &str) {
    let mut remainder = input;

    while !remainder.is_empty() {
        let next_bold = remainder.find("**");
        let next_italic = remainder.find('*');
        let next_underline = remainder.find("<u>");

        let mut candidates = Vec::new();
        if let Some(b) = next_bold {
            candidates.push((b, "bold"));
        }
        if let Some(i) = next_italic {
            if Some(i) != next_bold {
                candidates.push((i, "italic"));
            }
        }
        if let Some(u) = next_underline {
            candidates.push((u, "underline"));
        }

        candidates.sort_by_key(|&(pos, _)| pos);

        if let Some(&(first_pos, kind)) = candidates.first() {
            match kind {
                "underline" => {
                    if let Some(close_idx) = remainder[first_pos + 3..].find("</u>") {
                        let actual_close = first_pos + 3 + close_idx;
                        escape_typst_into(out, &remainder[..first_pos]);
                        out.push_str("#underline[");
                        format_inline_markdown_into(out, &remainder[first_pos + 3..actual_close]);
                        out.push(']');
                        remainder = &remainder[actual_close + 4..];
                        continue;
                    }
                }
                "bold" => {
                    if let Some(close_idx) = remainder[first_pos + 2..].find("**") {
                        let actual_close = first_pos + 2 + close_idx;
                        escape_typst_into(out, &remainder[..first_pos]);
                        out.push('*');
                        format_inline_markdown_into(out, &remainder[first_pos + 2..actual_close]);
                        out.push('*');
                        remainder = &remainder[actual_close + 2..];
                        continue;
                    }
                }
                "italic" => {
                    if let Some(close_idx) = remainder[first_pos + 1..].find('*') {
                        let actual_close = first_pos + 1 + close_idx;
                        escape_typst_into(out, &remainder[..first_pos]);
                        out.push('_');
                        format_inline_markdown_into(out, &remainder[first_pos + 1..actual_close]);
                        out.push('_');
                        remainder = &remainder[actual_close + 1..];
                        continue;
                    }
                }
                _ => {}
            }
        }

        escape_typst_into(out, remainder);
        break;
    }
}

/// Escapes characters that have syntactic meaning in Typst text directly into `out`.
fn escape_typst_into(out: &mut String, s: &str) {
    for c in s.chars() {
        match c {
            '#' | '@' | '$' => {
                out.push('\\');
                out.push(c);
            }
            _ => out.push(c),
        }
    }
}

fn escape_typst_special_chars(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    escape_typst_into(&mut out, s);
    out
}

/// Generates a complete Typst manuscript document for a `BookProject`.
pub fn compile_manuscript_to_typst(project: &BookProject) -> String {
    let mut doc = String::with_capacity(16 * 1024);

    let title_escaped = escape_typst_special_chars(&project.title);
    let author_escaped = escape_typst_special_chars(&project.author);

    // Document header and 6x9 Print Layout setup
    doc.push_str("// Print-Ready 6x9 Novel Manuscript Generated by The Scribe's Ledger\n");
    doc.push_str(&format!(
        "#set document(title: \"{}\", author: \"{}\")\n",
        title_escaped, author_escaped
    ));
    doc.push_str(
        r#"
#set page(
  width: 6in,
  height: 9in,
  margin: (
    inside: 0.85in,
    outside: 0.6in,
    top: 0.75in,
    bottom: 0.75in,
  ),
  header: context {
    let page_number = counter(page).get().first()
    // Suppress headers on first few front-matter pages or chapter starting pages
    if page_number > 2 {
      if calc.odd(page_number) {
        align(right, text(size: 8.5pt, font: "Libertinus Serif")[#smallcaps[#document.title] #h(1.5em) #str(page_number)])
      } else {
        align(left, text(size: 8.5pt, font: "Libertinus Serif")[#str(page_number) #h(1.5em) #smallcaps[#document.author]])
      }
    }
  },
  footer: none,
)

#set text(
  font: ("Libertinus Serif", "Linux Libertine", "Georgia"),
  size: 10.5pt,
  lang: "en",
)

#set par(
  justify: true,
  leading: 0.72em,
  first-line-indent: 1.5em,
)

// Scene break divider: elegant centered asterisks
#let scene-divider = {
  v(1.2em)
  align(center)[#text(size: 9pt, tracking: 0.4em)[\* \* \*]]
  v(1.2em)
}
"#,
    );

    // Front Matter
    for (i, item) in project.front_matter.iter().enumerate() {
        if i > 0 {
            doc.push_str("\n#pagebreak()\n\n");
        }
        if let Ok(content) = item.read_content() {
            let processed_content = replace_placeholders(&content, &project.title, &project.author);

            // Special handling for title page
            if item.name.contains("title_page") || item.name.contains("title") {
                doc.push_str("#align(center + horizon)[\n");
                doc.push_str(&format!(
                    "  #text(size: 22pt, weight: \"bold\")[{}]\n\n",
                    title_escaped
                ));
                doc.push_str("  #v(1.5em)\n");
                doc.push_str(&format!("  #text(size: 13pt)[by]\n\n"));
                doc.push_str("  #v(0.5em)\n");
                doc.push_str(&format!(
                    "  #text(size: 15pt, style: \"italic\")[{}]\n",
                    author_escaped
                ));
                doc.push_str("]\n");
            } else if item.name.contains("copyright") {
                doc.push_str("#align(bottom)[\n");
                doc.push_str("#set par(first-line-indent: 0pt)\n");
                doc.push_str("#set text(size: 8.5pt)\n");
                doc.push_str(&markdown_to_typst(&processed_content));
                doc.push_str("]\n");
            } else if item.name.contains("dedication") {
                doc.push_str("#align(center + horizon)[\n");
                doc.push_str("#set text(style: \"italic\")\n");
                doc.push_str(&markdown_to_typst(&processed_content));
                doc.push_str("]\n");
            } else {
                doc.push_str(&markdown_to_typst(&processed_content));
            }
        }
    }

    // Chapters and Scenes
    let mut numbered_chapter_count: usize = 0;

    for chapter in &project.chapters {
        doc.push_str("\n#pagebreak()\n\n");

        // Chapter Header in Final Print:
        // - Specialized chapters (Prologue, Epilogue, etc.) print their unique title (e.g. "Prologue").
        // - Regular numbered chapters print incrementing numbers ("1", "2") regardless of writer-only titles.
        match &chapter.kind {
            ChapterKind::Numbered => {
                numbered_chapter_count += 1;
                doc.push_str("{\n");
                doc.push_str("  #set align(center)\n");
                doc.push_str("  #v(2.5in)\n");
                doc.push_str(&format!(
                    "  #text(size: 18pt, weight: \"bold\")[{}]\n",
                    numbered_chapter_count
                ));
                doc.push_str("  #v(2.5em)\n");
                doc.push_str("}\n\n");
            }
            ChapterKind::Specialized(st) => {
                let print_title = escape_typst_special_chars(st);
                doc.push_str("{\n");
                doc.push_str("  #set align(center)\n");
                doc.push_str("  #v(2.5in)\n");
                doc.push_str(&format!(
                    "  #text(size: 18pt, weight: \"bold\")[{}]\n",
                    print_title
                ));
                doc.push_str("  #v(2.5em)\n");
                doc.push_str("}\n\n");
            }
        }

        for (scene_idx, scene) in chapter.scenes.iter().enumerate() {
            if scene_idx > 0 {
                doc.push_str("\n#scene-divider\n\n");
            }

            if let Ok(raw_content) = scene.read_content() {
                let processed_content =
                    replace_placeholders(&raw_content, &project.title, &project.author);
                doc.push_str(&markdown_to_typst(&processed_content));
                doc.push('\n');
            }
        }
    }

    doc
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn test_markdown_to_typst_formatting() {
        let md = "# Title\n\nThis is **bold**, this is *italic*, and this is <u>underlined</u>.\n\n> A great quote";
        let typst = markdown_to_typst(md);

        assert!(typst.contains("= Title"));
        assert!(typst.contains("*bold*"));
        assert!(typst.contains("_italic_"));
        assert!(typst.contains("#underline[underlined]"));
        assert!(typst.contains("#quote(block: true)["));
    }

    #[test]
    fn test_replace_placeholders() {
        let raw = "This novel, $Title, was penned by $Author. Also: $title and $author.";
        let res = replace_placeholders(raw, "Dune", "Frank Herbert");
        assert_eq!(
            res,
            "This novel, Dune, was penned by Frank Herbert. Also: Dune and Frank Herbert."
        );
    }

    #[test]
    fn test_compile_manuscript_to_typst_template() {
        let temp_dir = std::env::temp_dir().join("test_typst_template_v2");
        let _ = fs::remove_dir_all(&temp_dir);

        let mut project =
            BookProject::create_novel_blueprint(&temp_dir, "The Starbound Saga", "Eleanor Vance")
                .expect("create blueprint");

        // Rename chapter 1 and scene 1 with writer-only names
        project
            .rename_chapter(0, "My Secret Writer Chapter Title")
            .unwrap();
        project.rename_scene(0, 0, "My Secret Scene Note").unwrap();

        // Add a second regular chapter and rename it
        project.create_next_chapter().unwrap();
        project.rename_chapter(1, "Second Writer Chapter").unwrap();

        // Add a specialized Prologue at the beginning and Epilogue at the end
        project
            .create_specialized_chapter("Prologue", true)
            .unwrap();
        project
            .create_specialized_chapter("Epilogue", false)
            .unwrap();

        // Add a second scene to chapter 1 (which is now at index 1) to verify scene divider
        project.create_next_scene(1).unwrap();

        let typst = compile_manuscript_to_typst(&project);

        // Check 6x9 dimensions
        assert!(typst.contains("width: 6in"));
        assert!(typst.contains("height: 9in"));

        // Check mirrored inside/outside margins
        assert!(typst.contains("inside: 0.85in"));
        assert!(typst.contains("outside: 0.6in"));

        // Check chapter pagebreak and scene divider
        assert!(typst.contains("#pagebreak()"));
        assert!(typst.contains("#scene-divider"));

        // Check specialized chapters have their unique titles in print
        assert!(typst.contains("#text(size: 18pt, weight: \"bold\")[Prologue]"));
        assert!(typst.contains("#text(size: 18pt, weight: \"bold\")[Epilogue]"));

        // Check regular chapters have incrementing numbers ("1", "2") instead of "Chapter 1" or writer titles
        assert!(typst.contains("#text(size: 18pt, weight: \"bold\")[1]"));
        assert!(typst.contains("#text(size: 18pt, weight: \"bold\")[2]"));

        // Writer-only names must NOT appear in the compiled print output
        assert!(!typst.contains("My Secret Writer Chapter Title"));
        assert!(!typst.contains("Second Writer Chapter"));
        assert!(!typst.contains("My Secret Scene Note"));
        assert!(!typst.contains("Chapter 1"));

        let _ = fs::remove_dir_all(&temp_dir);
    }

    #[test]
    fn test_compile_to_pdf_with_typst() {
        let temp_dir = std::env::temp_dir().join("test_typst_direct_pdf_v2");
        let _ = fs::remove_dir_all(&temp_dir);

        let project =
            BookProject::create_novel_blueprint(&temp_dir, "Typst Direct Test", "A. Author")
                .expect("create blueprint");

        let pdf_out = temp_dir.join("print_ready_novel.pdf");
        let result = compile_to_pdf(&project, &pdf_out);

        if find_typst_binary().is_some() {
            let out_path = result.expect("Typst compile to pdf should succeed");
            assert!(out_path.exists());
            let bytes = fs::read(&out_path).expect("read pdf");
            assert!(bytes.starts_with(b"%PDF"));
        }

        let _ = fs::remove_dir_all(&temp_dir);
    }
}
